package sample

func Add(a, b int) int { return a + b }
func Unused() int { return 42 }
EOF
cat > sample_test.go <<'EOF'
package sample

import "testing"

func TestSampleOK(t *testing.T) {
	t.Run("SubtestOK", func(t *testing.T) {
		if Add(1, 2) != 3 {
			t.Error("bad")
		}
	})
}

func TestSampleNG(t *testing.T) {
	t.Error("this is an error")
}

func TestSampleSkip(t *testing.T) {
	t.Skip("skipping")
}
EOF
ls

